/**
 * App-level singletons + FR-23 event dimensions.
 *
 * Attribution/session controllers live here (rather than in `src/lib`) because
 * `src/lib` is dependency-injected and framework-free by contract; this module
 * is the wiring layer that binds it to `browserStorage` and build-time config.
 * Client components import these — never construct their own.
 */

import { attributionWindowDays } from "@/config";
import {
  createAttribution,
  type AttributionController,
} from "@/lib/attribution";
import { isKnownPlacement } from "@/lib/placements";
import {
  createSession,
  getDeviceType,
  type SessionController,
} from "@/lib/session";
import { browserStorage } from "@/lib/storage";
import type { Attribution, EventContext, LocationLike, Route } from "@/lib/types";
import { notifyAttribution } from "./subscription";

let attribution: AttributionController | null = null;
let session: SessionController | null = null;

export function getAppAttribution(): AttributionController {
  attribution ??= createAttribution({
    storage: browserStorage,
    windowDays: attributionWindowDays,
    isKnownPlacement,
  });
  return attribution;
}

export function getAppSession(): SessionController {
  session ??= createSession({ storage: browserStorage });
  return session;
}

export function currentRoute(): Route {
  if (typeof window === "undefined") return "other";
  return getAppAttribution().getRoute();
}

/**
 * Mutation wrappers — always go through these rather than the raw controller,
 * so `useSyncExternalStore` subscribers are notified and re-render.
 */
export function ensureAttribution(loc: LocationLike): Attribution | null {
  if (typeof window === "undefined") return null;
  const result = getAppAttribution().ensureFromUrl(loc);
  notifyAttribution();
  return result;
}

export function persistDiscountCode(code: string): void {
  getAppAttribution().setCode(code);
  notifyAttribution();
}

export function clearAttribution(): void {
  getAppAttribution().clear();
  notifyAttribution();
}

/**
 * FR-23 — every event carries these dimensions. Assembled at track time so a
 * return visit's later events still reflect the persisted attribution.
 * Safe to call during SSR (returns neutral defaults).
 */
export function commonContext(): EventContext {
  const hasDom = typeof window !== "undefined";
  const attr = hasDom ? getAppAttribution().read() : null;

  return {
    session_id: hasDom ? getAppSession().getSessionId() : "server",
    placement_code: attr?.placement ?? "unknown",
    route: attr?.ref === "qr" ? "qr" : hasDom ? "direct" : "other",
    offer: attr?.offer ?? null,
    referrer: hasDom ? document.referrer || null : null,
    device_type: hasDom ? getDeviceType(navigator.userAgent) : "desktop",
    timestamp: new Date().toISOString(),
  };
}
