/**
 * Discount codes — FR-16, FR-17 · C-12, C-13.
 *
 * Accepted risk (R1 / Q8): with FR-19 deferred there is no validation endpoint,
 * so the only controls are format strength, per-session uniqueness and expiry
 * terms. That is deliberate and documented in the architect spec (§14.2).
 */

import type { Attribution } from "./types";

/**
 * 31 symbols: A–Z minus I/L/O, and 2–9 minus 0/1 (FR-16's unambiguous alphabet).
 * Excludes 0, O, 1, I and L so codes survive being read aloud or typed by hand.
 */
export const DISCOUNT_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";

export const MIN_RAND_LEN = 4;
export const MAX_RAND_LEN = 16;

/** Injected so tests can prove the source without mocking globals. */
export type RandomSource = (count: number) => Uint32Array;

export const cryptoRandom: RandomSource = (count) => {
  const buffer = new Uint32Array(count);
  const webcrypto = globalThis.crypto;
  if (!webcrypto || typeof webcrypto.getRandomValues !== "function") {
    throw new Error("crypto.getRandomValues is unavailable (FR-17 requires CSPRNG)");
  }
  webcrypto.getRandomValues(buffer);
  return buffer;
};

/** Uppercase, strip everything outside [A-Z0-9], cap at 12 chars (§7.3). */
export function sanitisePlacement(placement: string): string {
  const cleaned = placement.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 12);
  return cleaned || "QR";
}

export function mintRandomSegment(
  length: number,
  random: RandomSource = cryptoRandom,
): string {
  const requested = Math.trunc(length);
  const bounded = Math.min(
    Math.max(Number.isFinite(requested) ? requested : MIN_RAND_LEN, MIN_RAND_LEN),
    MAX_RAND_LEN,
  );
  const values = random(bounded);
  let out = "";
  for (let i = 0; i < bounded; i++) {
    out += DISCOUNT_ALPHABET[values[i]! % DISCOUNT_ALPHABET.length]!;
  }
  return out;
}

/** `QR5-<PLACEMENT>-<RAND>` (FR-16). */
export function buildDiscountCode(
  placement: string,
  opts: { prefix: string; length: number; random?: RandomSource },
): string {
  return `${opts.prefix}-${sanitisePlacement(placement)}-${mintRandomSegment(opts.length, opts.random)}`;
}

export interface EnsureCodeDeps {
  read: () => Attribution | null;
  setCode: (code: string) => void;
  prefix: string;
  length: number;
  random?: RandomSource;
}

/**
 * Mint-once orchestrator. The `created` flag drives the
 * `discount_code_generated` event, and is `false` on every later call because
 * the code is persisted inside the attribution record (FR-16 stability).
 */
export function ensureDiscountCode(deps: EnsureCodeDeps): {
  code: string | null;
  created: boolean;
} {
  const attr = deps.read();
  if (!attr) return { code: null, created: false };
  if (attr.code) return { code: attr.code, created: false };

  const code = buildDiscountCode(attr.placement, {
    prefix: deps.prefix,
    length: deps.length,
    random: deps.random,
  });
  deps.setCode(code);
  return { code, created: true };
}
