/**
 * Analytics port — AD-7, C-11 (architect spec §8).
 *
 * Components only ever depend on the `Analytics` interface from `lib/types`.
 * The concrete provider (GA4 / PostHog / Plausible) is a `Sink`, so closing
 * open question Q5 is a one-file change rather than a redesign.
 *
 * `track()` is deliberately defensive: a broken analytics pipeline must never
 * break the conversion funnel (product principle 5 is about *us* measuring,
 * not the customer waiting on us).
 */

import type { Analytics, EventContext, EventName } from "@/lib/types";

/** What actually reaches the provider: common context merged with event props. */
export type WirePayload = EventContext & Record<string, unknown>;

export type Sink = (event: EventName, payload: WirePayload) => void;

/** AD-7 — the default sink until Q5 is answered. */
export const consoleSink: Sink = (event, payload) => {
  console.debug("[analytics]", event, payload);
};

export interface CreateAnalyticsOptions {
  sink: Sink;
  /** Supplies FR-23 dimensions; called lazily at track time. */
  context: () => EventContext;
  /** R6 — drop bot/QA traffic. */
  blocked?: () => boolean;
}

export function createAnalytics(opts: CreateAnalyticsOptions): Analytics {
  const { sink, context, blocked } = opts;
  return {
    track(event, props) {
      try {
        if (blocked?.()) return;
        const payload: WirePayload = {
          ...context(),
          ...(props as Record<string, unknown>),
        };
        sink(event, payload);
      } catch {
        /* swallow — analytics must never break the funnel */
      }
    },
  };
}

/** Named export kept for parity with the architect spec's `ConsoleAnalytics`. */
export class ConsoleAnalytics implements Analytics {
  constructor(private readonly context: () => EventContext) {}

  track<E extends EventName>(event: E, props: Parameters<Analytics["track"]>[1]) {
    try {
      console.debug("[analytics]", event, {
        ...this.context(),
        ...(props as Record<string, unknown>),
      });
    } catch {
      /* ignore */
    }
  }
}
