/**
 * Attribution — FR-2, FR-3, FR-4 · AD-5 · C-5, C-6, C-15.
 *
 * Rules that must not regress:
 *  1. Never overwrite an existing valid record — that is what preserves `code`
 *     and `ts` across the 30-day window (FR-16, C-6).
 *  2. An unknown/corrupt `v` resets silently; it must never throw (§7.2).
 *  3. Every read/write passes through the consent gate (C-15) so open question
 *     Q1 becomes a gate flip, not a refactor.
 */

import { base64UrlDecode, base64UrlEncode } from "./base64";
import type { StorageAdapter } from "./storage";
import type { Attribution, LocationLike, Route } from "./types";

export const ATTRIBUTION_COOKIE = "danga_attr";
export const ATTRIBUTION_SESSION_KEY = "danga_attr_session";

const SECONDS_PER_DAY = 86_400;

export interface AttributionDeps {
  storage: StorageAdapter;
  /** `ATTRIBUTION_WINDOW_DAYS` — 30 by default (FR-2). */
  windowDays: number;
  /** Defaults to allowing everything; swap in a real gate when Q1 closes (C-15). */
  consent?: () => boolean;
  /** Injected so `src/lib` never imports the JSON registry directly. */
  isKnownPlacement?: (code: string) => boolean;
  now?: () => Date;
}

/** Serialise for cookie + sessionStorage. Pure and independently testable. */
export function encodeAttribution(attr: Attribution): string {
  return base64UrlEncode(JSON.stringify(attr));
}

/**
 * Parse a stored record. Returns `null` for anything malformed rather than
 * throwing — a bad cookie must never break page load (FR-4).
 *
 * The validity rule here is **deliberately identical** to the inline boot
 * script's (`v === 1 && ref === "qr" && offer === "disc5"`). If the two ever
 * disagree, one side preserves a record the other discards, and attribution
 * silently sticks in a dead state. That equivalence is asserted by the
 * "accepts and rejects the same records" case in
 * `tests/unit/boot-script.test.ts`.
 */
export function decodeAttribution(raw: string | null | undefined): Attribution | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(base64UrlDecode(raw)) as Partial<Attribution>;
    if (
      parsed?.v !== 1 ||
      parsed.ref !== "qr" ||
      parsed.offer !== "disc5"
    ) {
      return null;
    }
    return {
      v: 1,
      ref: "qr",
      // Missing or garbled fields normalise to safe defaults instead of
      // failing the whole record: a partly-tampered cookie must not
      // permanently disable attribution (FR-4, C-6).
      placement:
        typeof parsed.placement === "string" ? parsed.placement : "unknown",
      placementValid: Boolean(parsed.placementValid),
      offer: "disc5",
      ts: typeof parsed.ts === "string" ? parsed.ts : new Date(0).toISOString(),
      code: typeof parsed.code === "string" ? parsed.code : "",
    };
  } catch {
    return null;
  }
}

/**
 * Detect QR context from the request URL (architect spec §9.1, FR-1, C-14).
 * The path wins when present; `?src=qr` alone still counts as a QR entry but
 * carries no placement.
 *
 * Matches `/l/<code>` at the root AND under a deploy subpath (e.g. GitHub
 * Project Pages serve the export with a `basePath` prefix, so the landing
 * arrives as `/<base>/l/<code>`). The `(?:^|\/)` anchor keeps parity with the
 * inline boot script — the two MUST stay interchangeable (see boot-script
 * tests). A segment that merely *contains* `l` (e.g. `/local/x`) does not
 * match: the `l` must be a whole path segment.
 */
export function parseQrContext(loc: LocationLike): {
  placement: string | null;
  hasQrContext: boolean;
} {
  const match = /(?:^|\/)l\/([^/?#]+)/.exec(loc.pathname ?? "");
  let placement: string | null = null;
  if (match?.[1]) {
    try {
      placement = decodeURIComponent(match[1]);
    } catch {
      placement = match[1];
    }
  }

  let hasSrcQr = false;
  try {
    hasSrcQr = new URLSearchParams(loc.search ?? "").get("src") === "qr";
  } catch {
    hasSrcQr = false;
  }

  return { placement, hasQrContext: placement !== null || hasSrcQr };
}

export function createAttribution(deps: AttributionDeps) {
  const storage = deps.storage;
  const windowDays = deps.windowDays;
  const consent = deps.consent ?? (() => true);
  const isKnown = deps.isKnownPlacement ?? (() => false);
  const now = deps.now ?? (() => new Date());

  /** Read order: sessionStorage → cookie → none (§7.2). */
  function read(): Attribution | null {
    if (!consent()) return null;
    return (
      decodeAttribution(storage.sessionGet(ATTRIBUTION_SESSION_KEY)) ??
      decodeAttribution(storage.getCookie(ATTRIBUTION_COOKIE))
    );
  }

  /** Write both media so a blocked cookie degrades to session scope (R5). */
  function write(attr: Attribution): void {
    if (!consent()) return;
    const raw = encodeAttribution(attr);
    storage.setCookie(ATTRIBUTION_COOKIE, raw, windowDays * SECONDS_PER_DAY);
    storage.sessionSet(ATTRIBUTION_SESSION_KEY, raw);
  }

  /**
   * Called from the inline boot script and again on hydration (idempotent).
   * Existing records are returned untouched — never overwritten.
   */
  function ensureFromUrl(loc: LocationLike): Attribution | null {
    if (!consent()) return null;

    const existing = read();
    if (existing) return existing;

    const { placement, hasQrContext } = parseQrContext(loc);
    if (!hasQrContext) return null;

    const known = placement !== null && isKnown(placement);
    const created: Attribution = {
      v: 1,
      ref: "qr",
      // Unknown/inactive codes collapse to "unknown" (FR-4, C-14, FR-23).
      placement: known ? placement! : "unknown",
      placementValid: known,
      offer: "disc5",
      ts: now().toISOString(),
      code: "",
    };
    write(created);
    return created;
  }

  /** Persist a minted code — only ever fills an empty slot (FR-16, C-6). */
  function setCode(code: string): void {
    const attr = read();
    if (!attr || attr.code) return;
    write({ ...attr, code });
  }

  function clear(): void {
    storage.removeCookie(ATTRIBUTION_COOKIE);
    storage.sessionRemove(ATTRIBUTION_SESSION_KEY);
  }

  function getRoute(): Route {
    return read()?.ref === "qr" ? "qr" : "direct";
  }

  return { read, write, ensureFromUrl, setCode, clear, getRoute };
}

export type AttributionController = ReturnType<typeof createAttribution>;
